!function(){"use strict";window.BudgetShared=window.BudgetShared||{},window.BudgetShared.Reminders={createReminder:async function(e,r){try{const n=await fetch(`/api/v1/reminders/${e}`,{method:"POST",headers:{"Content-Type":"application/json"},credentials:"include",body:JSON.stringify({reminder_datetime:r})});if(n.ok){const e=await n.json();return console.log("[BudgetShared.Reminders.createReminder] Reminder created:",e),e}{const e=await n.json();return console.error("[BudgetShared.Reminders.createReminder] API error:",e),null}}catch(e){return console.error("[BudgetShared.Reminders.createReminder] Network error:",e),null}},deleteReminder:async function(e){try{const r=await fetch(`/api/v1/reminders/${e}`,{method:"DELETE",credentials:"include"});if(r.ok||404===r.status)return console.log("[BudgetShared.Reminders.deleteReminder] Reminder deleted:",e),!0;{const e=await r.json();return console.error("[BudgetShared.Reminders.deleteReminder] API error:",e),!1}}catch(e){return console.error("[BudgetShared.Reminders.deleteReminder] Network error:",e),!1}},updateReminder:async function(e,r){try{const n=await fetch(`/api/v1/reminders/${e}`,{method:"PUT",headers:{"Content-Type":"application/json"},credentials:"include",body:JSON.stringify({reminder_datetime:r})});if(n.ok){const e=await n.json();return console.log("[BudgetShared.Reminders.updateReminder] Reminder updated:",e),e}{const e=await n.json();return console.error("[BudgetShared.Reminders.updateReminder] API error:",e),null}}catch(e){return console.error("[BudgetShared.Reminders.updateReminder] Network error:",e),null}}}}();